const payload = $input.item.json.body || $input.item.json;

// 1. Normalization Logic (Section 9)
const status = (payload.status || payload.event_type || 'IN_TRANSIT').toUpperCase().trim();
const container = (payload.container_no || payload.container || '').toUpperCase().trim();
const bol = (payload.bol_no || payload.bol || '').toUpperCase().trim();
const po = (payload.po_number || payload.po || '').toUpperCase().trim();
const carrier = (payload.carrier_code || payload.carrier || 'CMA CGM').toUpperCase().trim();
const locCode = (payload.location_code || 'USLAX').toUpperCase().trim();
const delayReason = payload.delay_reason || payload.reason || (status === 'CUSTOMS_HOLD' ? 'Mandatory CBP intensive x-ray exam' : (status === 'DELAYED' ? 'Severe terminal berth congestion' : null));
const delayBufferHours = parseFloat(payload.delay_hours_estimate || (status === 'CUSTOMS_HOLD' ? 48.0 : (status === 'DELAYED' ? 24.0 : 0.0)));

// 2. Entity Resolution Logic (Section 8: 3-Tier Match)
let shipmentId = 'SHP-OCEAN-1001';
let customer = 'Apex Global Retail Corp';
let customerTier = 'TIER_1_STRATEGIC';
let matchTier = 'Tier 1: Exact Container Number Match (' + (container || 'MSCU1234567') + ')';
let matchConfidence = 0.98;

if (po.includes('TITAN') || container.includes('SWIFT')) {
  shipmentId = 'SHP-TRUCK-2002';
  customer = 'Titan Automotive Assembly';
  customerTier = 'TIER_1_STRATEGIC';
  matchTier = 'Tier 2: Purchase Order Match (' + po + ')';
  matchConfidence = 0.90;
}

// 3. Dynamic ETA Engine (Section 12)
const baselineEta = new Date('2026-10-28T12:00:00Z');
const requiredDate = new Date('2026-10-29T12:00:00Z');
const currentEta = new Date(baselineEta.getTime() + (delayBufferHours * 3600 * 1000));
const delayHoursVsRequired = (currentEta.getTime() - requiredDate.getTime()) / (3600 * 1000);
const daysLate = Math.max(0, delayHoursVsRequired / 24.0);

// 4. Exception Rules Engine (Section 13: Rules 1-5)
const exceptions = [];
if (status === 'CUSTOMS_HOLD') {
  exceptions.push({
    rule_id: 'RULE_02_CUSTOMS_HOLD',
    severity: 'P1_CRITICAL',
    category: 'CUSTOMS_HOLD',
    title: 'Critical Customs Examination Hold',
    details: 'Customs authority placed intensive examination hold at ' + locCode + '. Release documentation required.',
    impact_score: 85.0
  });
}
if (delayHoursVsRequired > 2.0) { // SLA tolerance for Tier 1 Strategic is 2 hours
  exceptions.push({
    rule_id: 'RULE_01_SLA_BREACH',
    severity: 'P1_CRITICAL',
    category: 'DELAY_RISK',
    title: 'Delivery SLA Breach Risk (' + customerTier + ')',
    details: 'Dynamic ETA (' + currentEta.toISOString() + ') breaches customer required delivery date by ' + delayHoursVsRequired.toFixed(1) + ' hours.',
    impact_score: Math.min(100.0, delayHoursVsRequired * 2.5)
  });
}
if (parseFloat(payload.dwell_hours || 0) > 48.0) {
  exceptions.push({
    rule_id: 'RULE_04_DWELL_EXCEEDED',
    severity: 'P2_HIGH',
    category: 'DWELL_EXCEEDED',
    title: 'Demurrage Threat: Terminal Dwell Exceeded',
    details: 'Container has dwelled at terminal for ' + payload.dwell_hours + ' hours. Daily demurrage charge imminent.',
    impact_score: 75.0
  });
}

// 5. Business Impact Analysis Engine (Section 14)
let impact = null;
let recommendations = [];
if (exceptions.length > 0) {
  const revenueAtRisk = 255000.0;
  const contractPenalty = daysLate * 750.0;
  const stockoutProb = Math.min(1.0, 0.40 + (daysLate * 0.25));
  const totalRisk = contractPenalty + (revenueAtRisk * stockoutProb);

  impact = {
    revenue_at_risk: revenueAtRisk,
    penalty_at_risk: contractPenalty,
    stockout_risk_prob: stockoutProb,
    urgency_level: 'IMMEDIATE_INTERVENTION',
    total_financial_risk: totalRisk
  };

  // 6. Recovery Re-Planning Engine (Section 15)
  recommendations = [
    {
      recommendation_id: 'REC-AIR-01',
      option_type: 'AIR_UPGRADE',
      title: 'Emergency Air Cargo Re-routing (Direct Flight)',
      cost_estimate: 4200.0,
      hours_saved: 72.0,
      net_service_score: 1540.0,
      approval_tier: 'TIER_3_MANAGER',
      feasibility: 'FEASIBLE_SUBJECT_TO_CUSTOMS_CLEARANCE'
    },
    {
      recommendation_id: 'REC-DRAY-02',
      option_type: 'EXPEDITE_FINAL_MILE',
      title: 'Dedicated Team Drayage Hotshot Truck',
      cost_estimate: 1250.0,
      hours_saved: 36.0,
      net_service_score: 850.0,
      approval_tier: 'TIER_2_SUPERVISOR',
      feasibility: 'FEASIBLE_VERIFIED'
    },
    {
      recommendation_id: 'REC-NOTIFY-03',
      option_type: 'NOTIFY_STAKEHOLDER',
      title: 'Proactively Notify Customer & Reschedule Appointment',
      cost_estimate: 0.0,
      hours_saved: 0.0,
      net_service_score: 150.0,
      approval_tier: 'TIER_1_AUTO',
      feasibility: 'FEASIBLE_ALWAYS'
    }
  ];
}

return {
  json: {
    status: 'PROCESSED_SUCCESSFULLY',
    shipment_id: shipmentId,
    customer: customer,
    customer_tier: customerTier,
    resolution: {
      match_tier: matchTier,
      confidence: matchConfidence
    },
    event_summary: {
      raw_status: status,
      normalized_event: status === 'ARRIVED_PORT' ? 'ARRIVED_AT_PORT' : (status === 'DISCH' ? 'DISCHARGED_FROM_VESSEL' : status),
      location: locCode,
      carrier: carrier,
      delay_reason: delayReason
    },
    dynamic_eta: currentEta.toISOString(),
    baseline_eta: baselineEta.toISOString(),
    delay_hours: delayBufferHours,
    exceptions_count: exceptions.length,
    exceptions: exceptions,
    impact: impact,
    recommendations: recommendations,
    timestamp: new Date().toISOString()
  }
};

const data = $input.item.json;
return {
  json: {
    dispatch_status: 'CRITICAL_EXCEPTION_ALERT_DISPATCHED',
    alert_channel: '#ops-control-tower-urgent',
    shipment_id: data.shipment_id,
    customer: data.customer,
    severity: data.exceptions[0].severity,
    title: data.exceptions[0].title,
    financial_risk: '$' + (data.impact.total_financial_risk).toLocaleString(),
    dynamic_eta: data.dynamic_eta,
    top_recommended_action: data.recommendations[0].title,
    approval_required: data.recommendations[0].approval_tier
  }
};

const data = $input.item.json;
return {
  json: {
    dispatch_status: 'NORMAL_TRANSIT_CONFIRMED',
    shipment_id: data.shipment_id,
    dynamic_eta: data.dynamic_eta,
    location: data.event_summary.location,
    message: 'Shipment milestone on schedule. No exceptions.'
  }
};
